Q41.raw:
```sql
SELECT s.serv_lvl AS service_level, COUNT(CASE WHEN sd.ereig_cd = 'DLV' THEN 1 ELSE NULL END) AS delivered_shipments, COUNT(CASE WHEN sd.ereig_cd = 'DLV' AND sd.ereig_zeit > s.wunsch_lief_dat THEN 1 ELSE NULL END) AS late_shipments, ROUND(COUNT(CASE WHEN sd.ereig_cd = 'DLV' AND sd.ereig_zeit > s.wunsch_lief_dat THEN 1 ELSE NULL END) * 100.0 / COUNT(CASE WHEN sd.ereig_cd = 'DLV' THEN 1 ELSE NULL END), 1) AS late_pct FROM sndg s JOIN sdg_verfolg sd ON s.sndg_nr = sd.sndg_nr WHERE sd.ereig_cd = 'DLV' GROUP BY s.serv_lvl ORDER BY s.serv_lvl;
```
